# CONTRACT-003: FizeauService Service Interface

**Status:** Draft
**Owner:** Fizeau maintainers
**Replaces:** CONTRACT-002-ddx-harness-interface (deleted; entanglement-era contract)

## Purpose

This contract defines the public Go surface of the `fiz` module. The
service surface is the `FizeauService` interface plus the input/output struct types
referenced by its methods. The only public CLI embedding surface is the
`agentcli` mountable command tree described below. Anything else is internal
and may change without notice.

Consumers (DDx CLI, future HELIX/Dun integrations, the standalone `fiz`
binary, anything else) interact only through this surface. **They do not import
agent internal packages.** When new behavior is needed, consumers file an issue or
PR against this contract; agent maintainers decide whether the surface grows.

The native in-process Fizeau harness identity is `fiz`. The term `agent` is
reserved for real external AI-agent concepts or historical artifact names; it is
not a public alias for the native Fizeau route.

Implementation ownership and package boundaries are governed by
[ADR-008: Service Package and Transcript Boundaries](../adr/ADR-008-service-package-and-transcript-boundaries.md).
That ADR makes this contract the public facade, assigns transcript/progress
semantics to Fizeau, and treats downstream tools such as DDx as pass-through
consumers of public service events rather than owners of harness-native
transcript parsing.

## Module value proposition

`fiz` is the one stop shop for automatically routed one-shot
noninteractive agentic prompts. Two roles:

1. **Direct first-class agent** over native model providers (LM Studio, OpenRouter,
   Anthropic, etc.). Designed to be the high-performance choice for batch
   noninteractive tasks.
2. **Wrapper around other agents** — subprocess harnesses (claude, codex,
   opencode, pi, gemini) — used when their interactive features, vendor billing,
   specific capabilities, or comparison/fallback routing wants them in the
   candidate pool.

A single internal routing engine ranks `(harness, provider source, endpoint,
model)` candidates uniformly. Consumers see one surface; the internals decide
how to dispatch.

## Interface

```go
package agentlib

import (
    "context"
    "io"
    "time"
    "encoding/json"
)

// FizeauService is the entire public Go surface of the fiz module.
type FizeauService interface {
    // Execute runs an agent task in-process; emits Events on the channel until
    // the task terminates (channel closes). The final event (type=final) carries
    // status, normalized final_text, usage, cost, session log path, optional
    // message history, and routing_actual (the resolved fallback chain that fired).
    Execute(ctx context.Context, req ExecuteRequest) (<-chan Event, error)

    // TailSessionLog streams events from a previously-started or in-progress
    // session by ID. Used by clients (DDx workers, UIs) to subscribe to a run
    // started elsewhere — e.g., a server-managed worker that the CLI wants to
    // follow. Multi-subscriber-safe.
    TailSessionLog(ctx context.Context, sessionID string) (<-chan Event, error)

    // ListHarnesses returns metadata for every registered harness (native and
    // subprocess). HarnessInfo includes install state, supported permission
    // levels, supported reasoning values, and live quota when applicable.
    ListHarnesses(ctx context.Context) ([]HarnessInfo, error)

    // ListProviders returns providers known to the native `fiz` harness with
    // live status, configured-default markers, and cooldown state.
    ListProviders(ctx context.Context) ([]ProviderInfo, error)

    // ListModels returns models matching the filter. Implemented fields include
    // cost, perf signals, capabilities, context length, rank position, provider
    // source/type, and endpoint identity. Planned power-routing fields are
    // listed on ModelInfo below and land through agent-da67ebbe.
    ListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error)

    // ListProfiles, ResolveProfile, and ProfileAliases describe named power
    // policies. A profile is shorthand for a point or bounded range on the
    // model power curve, plus optional ranking preferences; it is not a closed
    // list of concrete models.
    ListProfiles(ctx context.Context) ([]ProfileInfo, error)
    ResolveProfile(ctx context.Context, name string) (*ResolvedProfile, error)
    ProfileAliases(ctx context.Context) (map[string]string, error)

    // HealthCheck triggers a fresh probe and updates internal state.
    // Target.Type is "harness" or "provider".
    HealthCheck(ctx context.Context, target HealthTarget) error

    // ResolveRoute resolves a single under-specified request to a concrete
    // (Harness, ProviderSource/Endpoint, Model). The returned RouteDecision is
    // informational: operator dashboards, route-status displays, and debug
    // surfaces. RouteDecision includes the selected endpoint, sticky-lease
    // evidence (status only; never the raw key), and endpoint utilization
    // evidence when available so operators can explain why a worker stayed
    // pinned or why a fresh key picked a specific endpoint. It is not
    // re-injectable into Execute. Execute always re-resolves on its own inputs
    // (idempotent for the same caller intent, modulo health changes which is
    // the intended behavior).
    ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error)

    // RecordRouteAttempt records availability feedback about externally routed
    // work. Non-success statuses create a same-process cooldown keyed by
    // harness/provider/model/endpoint; success clears matching active failures.
    RecordRouteAttempt(ctx context.Context, attempt RouteAttempt) error

    // RouteStatus returns global routing state across live provider/model
    // candidates: cooldowns, recent decisions, sticky assignment status,
    // selected endpoint, and observation-derived per-(provider source,
    // endpoint, model) latency / utilization evidence.
    // Distinct from per-request ResolveRoute — this is the read-only operator
    // dashboard view.
    RouteStatus(ctx context.Context) (*RouteStatusReport, error)

    // UsageReport aggregates token, cost, and reliability totals across the
    // service-owned session-log directory. CLI subcommands such as
    // `fiz usage` consume this projection rather than re-reading
    // session-log JSONL records.
    UsageReport(ctx context.Context, opts UsageReportOptions) (*UsageReport, error)

    // ListSessionLogs returns the historical session-log entries known to the
    // service (session id, mod time, size). Consumers display these without
    // touching the on-disk session-log layout.
    ListSessionLogs(ctx context.Context) ([]SessionLogEntry, error)

    // WriteSessionLog renders every event in the named session log to w as
    // indented JSON, one event per object. The format is service-owned;
    // consumers do not parse it back into private session-log structs.
    WriteSessionLog(ctx context.Context, sessionID string, w io.Writer) error

    // ReplaySession renders a human-readable conversation transcript for the
    // named session log onto w. Used by `fiz replay <id>`.
    ReplaySession(ctx context.Context, sessionID string, w io.Writer) error
}

// ValidateUsageSince returns nil when spec is a usage window value accepted by
// UsageReport. CLI subcommands call this to surface validation errors with
// exit-code 2 before invoking the service.
func ValidateUsageSince(spec string) error

// New constructs a FizeauService. Options is intentionally minimal.
func New(opts Options) (FizeauService, error)
```

**Sixteen methods total.** `Execute` is the primary verb; `TailSessionLog`,
`ListHarnesses`, `ListProviders`, `ListModels`, `ListProfiles`,
`ResolveProfile`, `ProfileAliases`, `HealthCheck`, `ResolveRoute`,
`RecordRouteAttempt`, and `RouteStatus` are the supporting routing/status
surface; `UsageReport`, `ListSessionLogs`, `WriteSessionLog`, and
`ReplaySession` are the historical session-log projection used by `fiz log`,
`replay`, and `usage`.

## Mountable CLI Surface

The standalone `fiz` binary and embedding callers use the same public
Cobra command tree from package `agentcli`:

```go
package agentcli

type MountOption func(...)

func MountCLI(opts ...MountOption) *cobra.Command
func WithUse(use string) MountOption
func WithShort(short string) MountOption
func WithLong(long string) MountOption
func WithStdin(stdin io.Reader) MountOption
func WithStdout(stdout io.Writer) MountOption
func WithStderr(stderr io.Writer) MountOption
func WithVersion(version, buildTime, gitCommit string) MountOption

type ExitError struct { Code int }
func ExitCode(err error) (int, bool)

type Options struct { Args []string; Stdin io.Reader; Stdout io.Writer; Stderr io.Writer; Version, BuildTime, GitCommit string }
func Run(opts Options) int
```

Implementation references: `agentcli/mount.go` defines `MountCLI`, mount
options, `ExitError`, and `ExitCode`; `agentcli/run.go` defines the non-exiting
`Run` runner; `cmd/agent/main.go` mounts the command and is the only
`fiz` command path that converts returned errors into `os.Exit`.

Contract guarantees for embedders:

- `MountCLI` returns a fresh, unattached `*cobra.Command` on each call.
- `WithUse`, `WithShort`, and `WithLong` customize help metadata without
  changing execution behavior.
- `WithStdin`, `WithStdout`, and `WithStderr` inject the streams used by the
  mounted root and delegated runner. Native subcommands should preserve the
  standalone command behavior; when a legacy implementation still writes to
  process streams internally, that is an implementation debt, not a license for
  embedding callers to parse private state.
- `WithVersion` supplies the version/build metadata printed by `--version`.
- Mounted execution never calls `os.Exit`; non-zero CLI outcomes are returned
  as `*ExitError`, and callers may use `ExitCode` to recover the process-style
  code. The standalone binary owns process termination in `cmd/agent/main.go`.
- Existing command paths are registered on the Cobra tree. Compatibility
  delegation may remain for the default prompt path and explicitly delegated
  commands, but migrated subcommands must not require callers to inject the
  `--` passthrough sentinel.

### Power-Routing Implementation Status

This contract distinguishes implemented surface from target power-routing
surface:

- Implemented today: `ListModels`, provider/endpoint identity, route decisions,
  route-attempt feedback, prompt-feature gates, and catalog reference methods.
- Planned through `agent-79e194aa`: profile power policy, `MinPower`, and
  `MaxPower` on `ServiceExecuteRequest`, `RouteRequest`, and `ModelFilter`.
- Planned through `agent-da67ebbe`: `ModelInfo` inventory fields for power,
  provider/deployment class or equivalent power provenance, availability,
  auto-routable, and exact-pin-only.
- Planned through `agent-7d537e4a`, `agent-005a0a30`, and `agent-de968c76`:
  power filtering, utility scoring, no-power best lowest-cost default, and
  statement-backed routing invariant tests.

## Public types

```go
type Options struct {
    ConfigPath string    // optional override; default $XDG_CONFIG_HOME/fizeau/config.yaml

package fizeau

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync/atomic"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/compaction"
	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
	"github.com/DocumentDrivenDX/fizeau/internal/serviceimpl"
	"github.com/DocumentDrivenDX/fizeau/internal/tool"
)

// generateSessionID returns a unique session identifier for a new Execute.
func generateSessionID() string {
	return fmt.Sprintf("svc-%d", time.Now().UnixNano())
}

// Execute runs an agent task in-process; emits Events on the returned
// channel until the task terminates (channel closes). The final event
// (type=final) carries status, usage, cost, session-log path, and the
// resolved fallback chain that fired.
//
// See CONTRACT-003 §"Behaviors the contract guarantees" for the full
// behavior contract this method honors:
//   - Orphan-model validation (Status=failed when Model unknown)
//   - Provider-deadline wrapping (Timeout + IdleTimeout + ProviderTimeout)
//   - StallPolicy enforcement (stall event before final)
//   - Route-reason attribution (routing_decision start, routing_actual final)
//   - OS-level subprocess cleanup on ctx.Done()
//   - Metadata bidirectional echo (events + session log)
//   - SessionLogDir per-request override
//
// Routing: under-specified requests (no Harness) are dispatched through
// internal/routing.Resolve via ResolveRoute. Callers can run with bare
// Profile/ModelRef/Model/Provider — the engine picks. NativeProvider must
// still be supplied for the native path until provider construction lands
// in a follow-up.
func (s *service) Execute(ctx context.Context, req ServiceExecuteRequest) (<-chan ServiceEvent, error) {
	// Boundary validation: reject unknown CachePolicy values before any
	// session state is opened or events are emitted. Beads C/D consume this
	// field; an unknown value is a caller programming error.
	if err := ValidateCachePolicy(req.CachePolicy); err != nil {
		return nil, err
	}
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}

	// Generate a session ID and register it in the hub so TailSessionLog
	// callers can subscribe before or during execution.
	sessionID := generateSessionID()
	fanout := s.executeEventFanout()
	fanout.openSession(sessionID)

	outer := make(chan ServiceEvent, 64)

	// ADR-006 §3/§4: capture the override context (user pin + unconstrained
	// auto decision) before route resolution so we can fire the matching
	// override / rejected_override event regardless of which path the route
	// resolution takes.
	overrideCtx := s.buildOverrideContext(ctx, req)

	// ADR-006 §5: record this request into the routing-quality store so
	// auto_acceptance_rate / override_disagreement_rate / class_breakdown
	// reflect both overridden and non-overridden traffic. The recorded
	// override payload carries no outcome — outcome aggregation for live
	// requests is best-effort and lives in session logs once that
	// persistence path lands.
	s.recordRoutingQualityForRequest(overrideCtx)

	// Resolve the route.
	decision, err := s.executeRouteResolver().resolveExecuteRoute(req)
	if err != nil {
		// NoViableProviderForNow is a transient quota signal — DDx
		// callers pause their drain loop on RetryAfter and resume.
		// Surface it directly (not via the fatal-final channel) so the
		// typed error reaches errors.As without log scraping.
		var quotaErr *NoViableProviderForNow
		if errors.As(err, &quotaErr) {
			fanout.closeSession(sessionID, ServiceEvent{})
			return nil, err
		}
		if isExplicitPinError(err) {
			// Emit a rejected_override event (no outcome) when the pin
			// fails pre-dispatch. Surface the typed error wrapped with
			// the rejected_override payload so callers that errors.As
			// the typed pin error still get it; callers wanting the
			// telemetry can extract via AsRejectedOverride.
			pinErr := err
			if overrideCtx != nil {
				if rejectedEv, payload, ok := makeRejectedOverrideEvent(overrideCtx, sessionID, pinErr, req.Metadata); ok {
					fanout.broadcastEvent(sessionID, rejectedEv)
					// Persist the rejected_override to the session log so
					// UsageReport's windowed scan (which sources from
					// session logs, not the in-memory ring) sees this
					// rejection. The pin failed pre-dispatch, so no
					// runExecute will open a log for this session — open
					// one briefly here, write session.start + the rejected
					// payload, and close.
					s.persistRejectedOverride(req, sessionID, payload)
					pinErr = &ErrRejectedOverride{Inner: err, Event: payload}
				}
			}
			fanout.closeSession(sessionID, ServiceEvent{})
			return nil, pinErr
		}
		// Still return a channel that yields a single failed final event so
		// downstream consumers don't have to special-case the error path.
		// Also close the hub session so TailSessionLog subscribers unblock.
		go func() {
			emitFatalFinal(outer, req.Metadata, "failed", err.Error())
			// Drain outer to get the final event and forward to hub.
			// emitFatalFinal closes outer; read the single event from it.
		}()
		// We can't easily intercept emitFatalFinal here, so close the hub
		// session with an empty final immediately — callers on TailSessionLog
		// for a failed-route session get an empty close.
		go func() {
			// Wait briefly for emitFatalFinal to write.
			time.Sleep(10 * time.Millisecond)
			fanout.closeSession(sessionID, ServiceEvent{})
		}()
		return outer, nil
	}

	// Metadata seam: every event we emit echoes req.Metadata.
	meta := req.Metadata

	// Wrap the inner channel through the hub so every event is broadcast to
	// TailSessionLog subscribers. The fan-out goroutine owns outer's close
	// and is responsible for inserting the override event (if any) immediately
	// before the final event per ADR-006 §7.
	inner := fanout.wrapExecuteWithHub(sessionID, outer, overrideCtx, meta)

	// Emit start-of-execution routing_decision so consumers know the picked
	// chain before any real work fires. The actual chain (post-fallback) is
	// stamped onto the final event's RoutingActual field.
	go s.runExecute(ctx, req, *decision, meta, inner, sessionID, overrideCtx)
	return outer, nil
}

// resolveExecuteRoute reduces the request to a concrete RouteDecision.
// The request is dispatched through the routing engine
// (internal/routing.Resolve) when under-specified, or accepted verbatim
// when Harness is set explicitly.
func (s *service) resolveExecuteRoute(req ServiceExecuteRequest) (*RouteDecision, error) {
	// If Harness is omitted, route through the engine. The engine defaults to
	// local-first and auto-selects from configured endpoints when no other
	// constraints are specified — an empty request is valid if providers exist.
	if req.Harness == "" {
		return s.resolveExecuteRouteWithEngine(req)
	}
	canonical := harnesses.ResolveHarnessAlias(req.Harness)
	if !s.registry.Has(canonical) {
		return nil, fmt.Errorf("unknown harness %q", req.Harness)
	}
	cfg, _ := s.registry.Get(canonical)
	if err := validateExplicitHarnessProfile(canonical, cfg, req.Profile); err != nil {
		return nil, err
	}
	if err := validateExplicitProvider(s.opts.ServiceConfig, cfg, req.Provider); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessReasoning(canonical, cfg, req.Reasoning); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessQuota(canonical, cfg); err != nil {
		return nil, err
	}
	resolvedModel := resolveSubprocessModelAlias(canonical, req.Model)
	decision := &RouteDecision{
		Harness:  canonical,
		Provider: req.Provider,
		Model:    resolvedModel,
		Reason:   "explicit",
		Power:    catalogPowerForModel(serviceRoutingCatalog(), resolvedModel),
	}
	if decision.Endpoint == "" {
		_, endpoint, _ := splitEndpointProviderRef(decision.Provider)
		decision.Endpoint = endpoint
	}
	return decision, nil
}

func validateExplicitHarnessQuota(name string, cfg harnesses.HarnessConfig) error {
	if !cfg.IsSubscription {
		return nil
	}
	now := time.Now()
	qs, ok := subscriptionQuotaForHarness(name, now)
	if !ok || !qs.Present || !qs.Fresh || qs.OK {
		return nil
	}
	return explicitQuotaUnavailable(name, qs.Windows, now)
}

func explicitQuotaUnavailable(name string, windows []harnesses.QuotaWindow, now time.Time) error {
	retryAfter := earliestQuotaResetAfter(windows, now)
	if retryAfter.IsZero() {
		retryAfter = now.Add(defaultQuotaRecoveryFallbackInterval)
	}
	return &NoViableProviderForNow{

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// fiz-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	if req.Harness != "" && req.Model != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
			return nil, err
		}
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	profile := req.Profile
	modelRef := req.ModelRef
	providerPreference, err := providerPreferenceForProfile(cat, profile)
	if err != nil {
		return &RouteDecision{}, err
	}
	in := s.buildRoutingInputsWithCatalog(ctx, cat)

	resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
	if modelErr != nil {
		result := &RouteDecision{Candidates: modelCandidates}
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(modelErr, result.Candidates)
	}

	rReq := routing.Request{
		Profile:               profile,
		ModelRef:              modelRef,
		Model:                 resolvedModel,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		MinPower:              req.MinPower,
		MaxPower:              req.MaxPower,
	}
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
		if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
			dec = edec
			err = eerr
		}
	}
	result := routeDecisionFromInternal(dec)
	if err != nil {
		if result == nil {
			result = &RouteDecision{}
		}
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(err, result.Candidates)
	}
	s.applyStickyRouteLease(req.CorrelationID, result)
	if result != nil && result.Endpoint == "" {
		_, endpoint, _ := splitEndpointProviderRef(result.Provider)
		result.Endpoint = endpoint
	}
	s.annotateRouteDecisionEvidence(result)
	// Cache the decision so RouteStatus can surface LastDecision.
	if result != nil {
		result.RequestedProfile = req.Profile
		result.PowerPolicy = RoutePowerPolicy{
			Profile:  req.Profile,
			MinPower: req.MinPower,
			MaxPower: req.MaxPower,
		}
		result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
		result.Power = catalogPowerForModel(cat, result.Model)
	}
	s.cacheRouteDecision(req.Model, result)
	return result, nil
}

func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
	if dec == nil {
		return nil
	}
	return &RouteDecision{
		Harness:    dec.Harness,
		Provider:   dec.Provider,
		Endpoint:   dec.Endpoint,
		Model:      dec.Model,
		Reason:     dec.Reason,
		Candidates: routeCandidatesFromInternal(dec.Candidates),
	}
}

func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
	if len(candidates) == 0 {
		return nil
	}
	out := make([]RouteCandidate, len(candidates))
	for i, candidate := range candidates {
		out[i] = routeCandidateFromInternal(candidate)
	}
	return out
}

func routeCandidateFromInternal(candidate routing.Candidate) RouteCandidate {
	return RouteCandidate{
		Harness:            candidate.Harness,
		Provider:           candidate.Provider,
		Endpoint:           candidate.Endpoint,
		Model:              candidate.Model,
		Score:              candidate.Score,
		CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
		CostSource:         candidate.CostSource,
		Eligible:           candidate.Eligible,
		Reason:             candidate.Reason,
		FilterReason:       publicFilterReason(candidate),
		Components: RouteCandidateComponents{
			Power:            candidate.Power,
			Cost:             candidate.CostUSDPer1kTokens,
			CostClass:        candidate.CostClass,
			LatencyMS:        candidate.LatencyMS,
			SpeedTPS:         candidate.SpeedTPS,
			SuccessRate:      candidate.SuccessRate,
			QuotaOK:          candidate.QuotaOK,
			QuotaPercentUsed: candidate.QuotaPercentUsed,
			QuotaTrend:       candidate.QuotaTrend,
			Capability:       capabilityScoreForCostClass(candidate.CostClass),
		},
	}
}

func (s *service) annotateRouteDecisionEvidence(decision *RouteDecision) {
	if s == nil || decision == nil {
		return
	}
	decision.Utilization = s.routeUtilizationEvidence(decision.Provider, decision.Endpoint, decision.Model)
	for i := range decision.Candidates {
		decision.Candidates[i].Utilization = s.routeUtilizationEvidence(
			decision.Candidates[i].Provider,
			decision.Candidates[i].Endpoint,
			decision.Candidates[i].Model,
		)
	}
}

func (s *service) routeUtilizationEvidence(provider, endpoint, model string) RouteUtilizationState {
	if s == nil || s.routeUtilization == nil {
		return RouteUtilizationState{}
	}
	keyProvider := strings.TrimSpace(provider)
	keyEndpoint := strings.TrimSpace(endpoint)
	if base, ep, ok := splitEndpointProviderRef(keyProvider); ok {
		keyProvider = base
		if keyEndpoint == "" {
			keyEndpoint = ep
		}
	}
	sample, ok := s.routeUtilization.Sample(keyProvider, keyEndpoint, model)
	if !ok {
		return RouteUtilizationState{}
	}
	return routeUtilizationStateFromSample(sample)
}

func routeUtilizationStateFromSample(sample utilization.EndpointUtilization) RouteUtilizationState {
	out := RouteUtilizationState{
		Source:     string(sample.Source),
		Freshness:  string(sample.Freshness),
		ObservedAt: sample.ObservedAt,
	}
	if sample.ActiveRequests != nil {
		out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
	}
	if sample.CacheUsage != nil {
		v := *sample.CacheUsage
		out.CachePressure = &v
	}
	if out.CachePressure == nil && sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
		total := 0
		if sample.ActiveRequests != nil {
			total += *sample.ActiveRequests
		}

package fizeau

// This file implements ListModels for the FizeauService service.
// It lives in the root package to avoid import cycles; provider and catalog
// data is injected via ServiceConfig (defined in service.go).
//
// Provider-backed models are discovered through /v1/models. Codex and Claude
// expose a separate harness-native surface backed by PTY/CLI evidence.

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"sync"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
	codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
	geminiharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/gemini"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
)

// ListModels returns models matching the filter, with full metadata.
// Empty filter returns all models from every reachable provider.
func (s *service) ListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error) {
	if filter.Harness != "" && harnesses.ResolveHarnessAlias(filter.Harness) != "fiz" {
		return s.listModelsForSubprocessHarness(filter), nil
	}

	sc := s.opts.ServiceConfig
	if sc == nil {
		return nil, fmt.Errorf("service: no ServiceConfig provided; pass ServiceOptions.ServiceConfig")
	}

	// Load the model catalog once for cross-referencing.
	cat, _ := modelcatalog.Default() // ignore error: catalog miss is non-fatal

	defaultProviderName := sc.DefaultProviderName()

	names := sc.ProviderNames()

	type indexedModels struct {
		idx    int
		models []ModelInfo
	}
	results := make([]indexedModels, len(names))
	var wg sync.WaitGroup

	for i, name := range names {
		// Apply provider filter.
		if filter.Provider != "" && filter.Provider != name {
			results[i] = indexedModels{idx: i, models: nil}
			continue
		}
		// Apply harness filter: providers are served by the "fiz" harness.
		if filter.Harness != "" && harnesses.ResolveHarnessAlias(filter.Harness) != "fiz" {
			results[i] = indexedModels{idx: i, models: nil}
			continue
		}

		wg.Add(1)
		go func(idx int, providerName string) {
			defer wg.Done()

			entry, ok := sc.Provider(providerName)
			if !ok {
				results[idx] = indexedModels{idx: idx, models: nil}
				return
			}

			isDefaultProvider := providerName == defaultProviderName
			models := listModelsForProvider(ctx, providerName, entry, isDefaultProvider, sc, cat)
			results[idx] = indexedModels{idx: idx, models: models}
		}(i, name)
	}
	wg.Wait()

	// Flatten in stable provider order.
	var out []ModelInfo
	for _, r := range results {
		out = append(out, r.models...)
	}
	return out, nil
}

func (s *service) listModelsForSubprocessHarness(filter ModelFilter) []ModelInfo {
	name := harnesses.ResolveHarnessAlias(filter.Harness)
	cfg, ok := s.registry.Get(name)
	modelIDs := subprocessHarnessModelIDs(name, cfg)
	if !ok || cfg.IsHTTPProvider || cfg.IsLocal || len(modelIDs) == 0 {
		return nil
	}
	if filter.Provider != "" && filter.Provider != name {
		return nil
	}
	cat, _ := modelcatalog.Default()
	catalogRefs := catalogRefsForHarness(cat, name)
	out := make([]ModelInfo, 0, len(modelIDs))
	for i, id := range modelIDs {
		info := ModelInfo{
			ID:           id,
			Provider:     name,
			Harness:      name,
			EndpointName: name,
			Capabilities: []string{"streaming", "tool_use"},
			Available:    true,
			IsDefault:    cfg.DefaultModel != "" && id == cfg.DefaultModel,
			CatalogRef:   catalogRefs[id],
			RankPosition: i,
		}
		if cat != nil {
			info.ContextLength = resolveContextLength(context.Background(), ServiceProviderEntry{}, id, cat)
			info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
			info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
		}
		out = append(out, info)
	}
	return out
}

func subprocessHarnessModelIDs(name string, cfg harnesses.HarnessConfig) []string {
	models := append([]string(nil), cfg.Models...)
	switch name {
	case "claude":
		snapshot := claudeharness.DefaultClaudeModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"sonnet", "opus", "haiku"} {
			resolved := claudeharness.ResolveClaudeFamilyAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	case "codex":
		snapshot := codexharness.DefaultCodexModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"gpt", "gpt-5"} {
			resolved := codexharness.ResolveCodexModelAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	case "gemini":
		snapshot := geminiharness.DefaultGeminiModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"gemini", "gemini-2.5"} {
			resolved := geminiharness.ResolveGeminiModelAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	}
	return models
}

func resolveSubprocessModelAlias(harness, model string) string {
	switch harness {
	case "claude":
		return claudeCLIExecutableModel(model)
	case "codex":
		return codexharness.ResolveCodexModelAlias(model, codexharness.DefaultCodexModelDiscovery())
	case "gemini":
		return geminiharness.ResolveGeminiModelAlias(model, geminiharness.DefaultGeminiModelDiscovery())
	default:
		return model
	}
}

func claudeCLIExecutableModel(model string) string {
	normalized := strings.ToLower(strings.TrimSpace(model))
	switch {
	case normalized == "sonnet" || strings.HasPrefix(normalized, "sonnet-") || strings.HasPrefix(normalized, "claude-sonnet-"):
		return "sonnet"
	case normalized == "opus" || strings.HasPrefix(normalized, "opus-") || strings.HasPrefix(normalized, "claude-opus-"):
		return "opus"
	case normalized == "haiku" || strings.HasPrefix(normalized, "haiku-") || strings.HasPrefix(normalized, "claude-haiku-"):
		return "haiku"
	default:
		return model
	}
}

func appendUniqueModelIDs(values []string, additions ...string) []string {
	for _, value := range additions {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		found := false
		for _, existing := range values {
			if existing == value {
				found = true
				break
			}
		}
		if !found {
			values = append(values, value)
		}
	}
	return values
}

func catalogRefsForHarness(cat *modelcatalog.Catalog, harness string) map[string]string {
	if cat == nil {
		return nil
	}
	switch harness {
	case "codex":
		return cat.AllConcreteModels(modelcatalog.SurfaceCodex)
	case "claude":
		return cat.AllConcreteModels(modelcatalog.SurfaceClaudeCode)
	case "gemini":
		return cat.AllConcreteModels(modelcatalog.SurfaceGemini)
	default:
		return nil
	}
}

